From f3daf12e6091d5fbfccab811062cd3413ca5e8e8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:06:40 +0100
Subject: [PATCH] containmentlayoutmanager: add container padding after its
 bindings are set

A widget moved to another screen got a container sized from its applet
before the container's padding bindings were evaluated, so the padding
counted as zero and the widget lost it on every move. Size it after that.

BUG: 522198
---
 .../containmentlayoutmanager/appletslayout.cpp | 18 ++++++++----------
 1 file changed, 8 insertions(+), 10 deletions(-)

diff --git a/components/containmentlayoutmanager/appletslayout.cpp b/components/containmentlayoutmanager/appletslayout.cpp
index a3cee50db3..95d5e5637e 100644
--- a/components/containmentlayoutmanager/appletslayout.cpp
+++ b/components/containmentlayoutmanager/appletslayout.cpp
@@ -769,21 +769,19 @@ AppletContainer *AppletsLayout::createContainerForApplet(PlasmaQuick::AppletQuic

     const bool geometryWasSaved = m_layoutManager->restoreItem(container);

-    if (!geometryWasSaved) {
-        container->setPosition(QPointF(appletItem->x() - container->leftPadding(), appletItem->y() - container->topPadding()));
-
-        if (!appletSize.isEmpty()) {
-            container->setSize(QSizeF(qMax(m_minimumItemSize.width(), appletSize.width() + container->leftPadding() + container->rightPadding()),
-                                      qMax(m_minimumItemSize.height(), appletSize.height() + container->topPadding() + container->bottomPadding())));
-        }
-    }
-
     if (m_appletContainerComponent && createdFromQml) {
         m_appletContainerComponent->completeCreate();
     }

     // NOTE: This has to be done here as we need the component completed to have all the bindings evaluated
-    if (!geometryWasSaved && appletSize.isEmpty()) {
+    if (!geometryWasSaved) {
+        container->setPosition(QPointF(appletItem->x() - container->leftPadding(), appletItem->y() - container->topPadding()));
+    }
+
+    if (!geometryWasSaved && !appletSize.isEmpty()) {
+        container->setSize(QSizeF(qMax(m_minimumItemSize.width(), appletSize.width() + container->leftPadding() + container->rightPadding()),
+                                  qMax(m_minimumItemSize.height(), appletSize.height() + container->topPadding() + container->bottomPadding())));
+    } else if (!geometryWasSaved) {
         if (container->initialSize().width() > m_minimumItemSize.width() && container->initialSize().height() > m_minimumItemSize.height()) {
             const QSizeF size = m_layoutManager->cellAlignedContainingSize(container->initialSize());
             container->setSize(size);
-- 
